private void notifyInterestedUsers(User seller, ProductSize productSize, int bidPrice) {
    String productName = productSize.getProductColor().getProduct().getName();
    String message = String.format("관심 상품 %s (사이즈 %s)에 새 판매 입찰이 등록되었습니다. 판매 희망가 %d원",
            productName, productSize.getSize(), bidPrice);

    interestQueryService.findAllByProductColorId(productSize.getProductColor().getId()).stream()
            .map(Interest::getUser)
            .filter(user -> !user.getId().equals(seller.getId()))
            .filter(User::isActive)
            .forEach(user -> notificationCommandService.createNotification(
                    user.getId(),
                    NotificationCategory.SHOPPING,
                    NotificationType.FAVORITE,
                    message
            ));
}

